        #original-menu {
            position: static;
            height: 56px;
            z-index: 10
        }

        #original-menu ul>li {
            position: relative;
            display: flex;
            flex-shrink: 0;
        }

        #Ooiix-menuList>li>a {
            position: relative;
            display: flex;
            font-size: 16px;
            color: var(--main-menu-text-color);
            font-weight: 500;
            text-transform: capitalize;
            padding: 0 20px;
