        }

        #original-menu ul>li>ul {
            position: absolute;
            float: left;
            left: 0;
            top: 60px;
            width: 180px;
            background: var(--submenu-bg-color);
            z-index: 99999;
            visibility: hidden;
            opacity: 0;
            -webkit-transform: translateY(-10px);
            transform: translateY(-10px);
            padding: 0;
            box-shadow: 0 2px 5px 0 rgba(0, 0, 0, 0.15), 0 2px 10px 0 rgba(0, 0, 0, 0.17)
        }

        #original-menu ul>li>ul>li>ul {
            position: absolute;
            top: 0;
            left: 100%;
            -webkit-transform: translateX(-10px);
            transform: translateX(-10px);
            margin: 0
        }

        #original-menu ul>li>ul>li {
            display: block;
            float: none;
            position: relative
        }

        #original-menu ul>li>ul>li a {
            position: relative;
            display: block;
            height: 36px;
            font-size: 13px;
            color: var(--sub-menu-text-color);
            line-height: 36px;
            font-weight: 600;
            box-sizing: border-box;
            padding: 0 15px;
            margin: 0;
            border-bottom: 1px solid rgba(155, 155, 155, 0.07)
        }

        #original-menu ul>li>ul>li:last-child a {
            border: 0
        }

        #original-menu ul>li>ul>li:hover>a {
            opacity: 0.8
        }

        #original-menu ul>li.sub-tab>a:after,
        #original-menu ul>li.sub-has>a:after {
            content: '\e5cf';
            font-family: 'Material Icons Round';
            font-size: 16px;
            font-weight: 400;
            margin: 0 0 0 5px
        }

        #original-menu ul>li>ul>li.sub-tab>a:after {
            content: '\e5cc';
            float: right;
            margin: 0
        }

        #original-menu ul>li:hover>ul,
        #original-menu ul>li>ul>li:hover>ul {
            visibility: visible;
            opacity: 1;
            -webkit-backface-visibility: hidden;
            backface-visibility: hidden;
            -webkit-transform: translate(0);
            transform: translate(0)
        }

        #original-menu ul ul {
            transition: all .35s ease
        }

        .loading-icon {
            width: 100%;
            height: 100%;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .raw-box .loading-icon {
            height: 185px
        }

        .loading-icon:after {
            content: "";
            width: 40px;
            height: 40px;
            border-radius: 50%;
            border: 2px solid var(--main-text-color);
            border-right: 2px solid #c1c1c1;
            display: inline-block;
            animation: runload 0.6s infinite
        }

        @-webkit-keyframes runload {
            0% {
                -webkit-transform: rotate(0deg);
                transform: rotate(0deg)
            }

            to {
                -webkit-transform: rotate(1turn);
                transform: rotate(1turn)
            }
        }

        @keyframes runload {
            0% {
                -webkit-transform: rotate(0deg);
                transform: rotate(0deg)
            }

            to {
                -webkit-transform: rotate(1turn);
                transform: rotate(1turn)
            }
        }

        .loading-frame {
            -webkit-animation-duration: .5s;
            animation-duration: .5s;
            -webkit-animation-fill-mode: both;
            animation-fill-mode: both
        }

        @keyframes fadeIn {
            from {
                opacity: 0
            }

            to {
                opacity: 1
            }
        }

        .run-time {
            animation-name: fadeIn
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translate3d(0, 5px, 0)
            }

            to {
                opacity: 1;
                transform: translate3d(0, 0, 0)
            }
        }

        .load-time {
            animation-name: fadeInUp
        }

        .overlay {
            visibility: hidden;
            opacity: 0;
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            z-index: 1000;
            margin: 0;
            transition: all .25s ease
        }

        .hamburger:before {
            content: "\e5d2";
            font-family: 'Material Icons Round';
            font-size: 24px;
            font-weight: 400
        }

        #inner-menu {
            display: none;
            position: fixed;
            width: 80%;
            height: 100%;
            top: 0;
            left: 0;
            bottom: 0;
            background: var(--mobile-menu-bg);
            overflow: auto;
            z-index: 1010;
            left: 0;
            -webkit-transform: translateX(-100%);
            transform: translateX(-100%);
            visibility: hidden;
            box-shadow: 3px 0 7px rgba(0, 0, 0, 0.1);
            -webkit-transition: all .5s cubic-bezier(.79, .14, .15, .86);
            -moz-transition: all .5s cubic-bezier(.79, .14, .15, .86);
            -o-transition: all .5s cubic-bezier(.79, .14, .15, .86);
            transition: all .5s cubic-bezier(.79, .14, .15, .86)
        }

        .spring-open #inner-menu {
            -webkit-transform: translateX(0);
            transform: translateX(0);
            visibility: visible;
            opacity: .99;
            -webkit-transition: all .5s cubic-bezier(.79, .14, .15, .86);
            -moz-transition: all .5s cubic-bezier(.79, .14, .15, .86);
            -o-transition: all .5s cubic-bezier(.79, .14, .15, .86);
            transition: all .5s cubic-bezier(.79, .14, .15, .86)
        }

        .inner-container {
            display: flex;
            padding: 10px 0;
            margin: 0;
            box-shadow: 3px 2px 4px 1px rgb(135 135 135 / 0.20);
            opacity: 0;
            transition: all ease-in-out .3s;
            justify-content: flex-end;
            align-items: center;
        }

        #inner-menu {
            transition: all .6s ease-in-out
        }

        .hide-mobile-menu {
            display: block;
            color: var(--main-menu-text-color);
            font-size: 20px;
            line-height: 28px;
            text-align: center;
            cursor: pointer;
            z-index: 20;
            background: rgb(137 137 137 / 0.10);
            border-radius: 4px;
            padding: 0 12px;
            margin: 0 10px 0 0;
            transition: transform ease-out .2s;
        }

        .hide-mobile-menu:hover {
            opacity: 0.8;
        }

        .hide-mobile-menu:before {
            content: "\e5cd";
            font-family: 'Material Icons Round';
            font-weight: 400
        }

        .spring-open .inner-container,
        .spring-open .mobile-container {
            opacity: 1
        }

        .mobile-container {
            display: flex;
            flex-direction: column;
            opacity: 0;
            justify-content: space-between;
            float: left;
            width: 100%;
            height: calc(100% - 11%);
            transition: all ease-in-out .3s
        }

        .social-mobile ul {
            margin: 0 0 0 15px;
            float: left;
        }

        .post-inner-data.flex {
            display: flex;
            align-content: center;
        }

        .post-inner-user {
            position: relative;
            float: left;
        }

        span.author-image {
            position: relative;
            display: block;
            height: 40px;
            width: 40px;
        }

        span.author-image img {
            border-radius: 50%;
            padding: 1px;
            border: 1px solid var(--button-bg-color);
        }

        .mobile-menu {
            position: relative;
            float: left;
            width: 100%;
            box-sizing: border-box;
            padding: 0 25px 0 0;
        }

        ul#Ooiix-menuList {
            display: flex;
            height: 56px;
            margin: 0 0 0 15px;
        }

        .mobile-menu>ul {
            margin: 0
        }

        #original-menu .fa {
            padding: 0 5px
        }

        .mobile-menu .fa {
            margin: 5px;
            padding: auto
        }

        .mobile-menu .m-sub {
            display: none;
            padding: 0
        }

        .mobile-menu ul li {
            position: relative;
            display: block;
            overflow: hidden;
            float: left;
            width: 100%;
            font-size: 14px;
            font-weight: 600;
            margin: 0;
            padding: 0
        }

        .mobile-menu>ul li ul {
            overflow: hidden
        }

        .mobile-menu>ul>li {
            border-bottom: 1px solid rgb(181 181 181 / 0.20)
        }

        .mobile-menu>ul>li.sub-tab>a:after,
        .mobile-menu>ul>li>ul>li.sub-tab>a:after {
            font-family: 'Material Icons Round';
            font-weight: 400;
            content: "\e5cf";
            font-size: 24px;
            vertical-align: middle;
        }

        .mobile-menu ul li.sub-tab.show>a:after {
            content: '\e5ce'
        }

        .mobile-menu ul li a:hover,
        .mobile-menu ul li.sub-tab.show>a,
        .mobile-menu ul li.sub-tab.show>.submenu-toggle {
            opacity: 0.8
        }

        .mobile-menu>ul>li>ul>li a {
            display: flex;
            font-size: 15px;
            font-weight: 400;
            color: var(--mobile-text-color);
            padding: 5px 0 5px 15px;
            margin: 0 0 8px;
            justify-content: space-between;
            flex-wrap: wrap;
        }

        .mobile-menu>ul>li>ul>li a:before {
            content: "\e061";
            font-family: 'Material Icons Round';
            font-style: normal;
            font-weight: 400;
            color: rgb(88 88 88 / 0.42);
            font-size: 6px;
            padding-right: 5px;
            position: absolute;
            left: 4px;
            vertical-align: middle;
        }

        .mobile-menu>ul>li>ul>li>ul>li>a:before {
            left: 18px;
        }

        .mobile-menu>ul>li>ul>li>ul>li>a {
            padding: 5px 0 5px 30px
        }

        .mobile-menu ul>li>.submenu-toggle:hover {
            opacity: 0.8;
        }

        .fixed-nos {
            position: fixed;
            top: -80px;
            left: 0;
            width: 100%;
            z-index: 990;
            box-shadow: none;
            transition: top .17s ease
        }

        .spring-open .fixed-nos {
            top: 0
        }

        .spring-open {
            overflow: hidden;
            left: 0;
            right: 0
        }

        .search-wrap {
            position: relative;
            display: flex;
            height: 56px;
            align-items: center;
            margin: 0;
        }

        #search-flex {
            display: none;
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 56px;
            line-height: 56px;
            z-index: 25;
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        .search-flex-container {
            display: flex;
            justify-content: space-between;
            align-items: center;
            position: relative;
            float: right;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0);
            overflow: hidden;
            margin: 0;
            animation: animateSearch .20s ease
        }

        .search-flex-container .search-form {
            position: relative;
            height: 34px;
            line-height: 34px;
            background-color: rgb(139 139 139 / 0.16);
            flex: 1;
            padding: 0 0 0 10px;
            border: 0;
            border-radius: 4px 0 0 4px;
        }

        .search-flex-container .search-input {
            position: relative;
            width: 100%;
            height: 35px;
            background: transparent;
            color: var(--search-bt-text);
            font-size: 15px;
            font-weight: 400;
            padding: 0 15px 0 0;
            border: 0;
        }

        .search-flex-container .search-input:focus,
        .search-flex-container .search-input::placeholder {
            color: var(--search-bt-text);
            outline: none
        }

        .search-flex-container .search-input::placeholder {
            opacity: .70
        }

        .search-hidden:after {
            content: '\e5cd';
            font-family: 'Material Icons Round';
            font-weight: 400;
            margin: 0;
        }

        @-webkit-keyframes animateSearch {
            0% {
                width: 80%;
                opacity: 0
            }

            100% {
                width: 100%;
                opacity: 1
            }
        }

        .search-flex-close {
            width: 34px;
            height: 34px;
            border-radius: 0 4px 4px 0;
            background: rgb(139 139 139 / 0.16);
            color: var(--search-bt-text);
            font-size: 24px;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: transform ease-out .2s;
            z-index: 20;
            padding: 0;
            margin: 0;
        }

        .search-flex-close:hover {
            opacity: 0.8;
        }

        .search-button-flex {
            color: var(--button-text-color);
            width: 40px;
            height: 40px;
            font-size: 26px;
            text-align: center;
            line-height: 40px;
            cursor: pointer;
            z-index: 20;
            padding: 0;
            margin: 0;
            transition: margin .25s ease;
        }

        .search-button-flex:before {
            content: "\e8b6";
            font-family: 'Material Icons Round';
            font-weight: 400
        }

        input[type="search"]::-webkit-search-decoration,
        input[type="search"]::-webkit-search-cancel-button,
        input[type="search"]::-webkit-search-results-button,
        input[type="search"]::-webkit-search-results-decoration {
            display: none;
        }

        input.search-input[type=text] {
            width: 83%;
            height: 60px;
            display: block
        }

        .search-input input {
            border-radius: 5px;
            padding: 5px 10px;
            width: 98%;
            border: 2px solid #eee
        }

        #hidden-widget-container,
