        .StickyBox {
            position: fixed;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            align-items: center;
            justify-content: center;
            opacity: 0;
            visibility: hidden;
            transform: translate3d(0, 72%, 0);
            transition: all .2s ease;
            z-index: 15151515;
        }

        .show-share .StickyBox {
            opacity: 1;
            visibility: visible;
            transform: translate3d(0, 0, 0);
        }

        .StickyTab {
            display: flex;
            flex-direction: row;
            align-content: center;
            justify-content: space-between;
            align-items: center;
            width: 100%;
            box-sizing: border-box;
            padding: 0 0 20px;
            margin: 0 0 10px;
            color: var(--title-share);
            border-bottom: 1px solid rgb(92 92 92 / 0.17);
        }

        .StickyType {
            position: relative;
            display: block;
            float: left;
            font-size: 15px;
            font-weight: 700;
        }

        .copy-section {
            width: 100%;
        }

        .copy-section .title {
            font-size: 14px;
            font-weight: 700;
            padding: 0 20px;
        }

        .copy-post {
            display: flex;
            align-items: center;
            align-content: center;
            box-sizing: border-box;
            position: relative;
            justify-content: center;
            margin: 10px 20px 0;
        }

        .copy-post:before {
            content: '\e157';
            font-weight: 400;
            font-family: 'Material Icons Round';
            position: absolute;
            left: 12px;
            font-size: 19px;
            color: var(--theme-text-color)
        }

        .rtl .copy-post:before {
