            display: flex;
            flex-wrap: wrap;
            justify-content: space-between;
            flex-direction: column;
        }

        #room-box .modal-box .modal-grid {
            width: calc((100% - 15px) / 2);
        }

        .modal-box {
            display: flex;
            justify-content: space-around;
            flex-wrap: wrap;
        }

        .modal-grid.item0 .post-filter-inner {
