        }

        .raw-main-wrapper {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            grid-gap: 25px;
            justify-items: start;
            align-items: start;
        }

        .block-step.item0 {
            grid-column: 1/2;
            grid-row: 1/2;
        }

        .block-step.item1 {
            grid-column: 2/3;
            grid-row: 1/2;
        }

        .block-step.item2 {
            grid-column: 3/4;
            grid-row: 1/2;
        }

        .block-step {
            position: relative;
            float: left;
            width: 100%;
            overflow: hidden;
        }

        .block-step .block-thumb {
            position: relative;
            width: 100%;
            height: 100%;
            overflow: hidden;
            border-radius: 4px;
        }

        .block-step .block-thumb .post-filter-link {
            display: block;
            width: 100%;
            height: 235px;
            overflow: hidden;
            box-sizing: border-box;
        }

        .type-block2 .widget-content {
            background-image: url(../blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEi5sN0lFvAUZyXhXrCJ_yEsjeiNPs3rqeKtpmF3gOw/s16000/dots.png);
            background-position: unset;
            background-repeat: repeat;
            padding: 33px;
            box-sizing: border-box;
        }

        .block-wrapper {
            position: relative;
            display: flex;
            width: 100%;
            margin: 0;
            justify-content: space-between;
            background: var(--body-color-main);
            border-radius: 5px
        }

        .block-combo {
            display: grid;
            grid-gap: 12px;
            margin: 0;
            width: 45%;
            grid-template-columns: repeat(2, 1fr);
        }

        .block-module.item0 {
            position: relative;
            width: calc(55% - 1em);
        }

        .block-module.item0 .post-filter-inner {
            width: 100%;
            height: 520px;
            border-radius: 4px;
        }

        .block-module.item1 {
            grid-column: 1/2;
            grid-row: 1/2;
        }

        .block-module.item2 {
            grid-column: 2/3;
            grid-row: 1/2;
        }

        .block-module.item3 {
            grid-column: 1/2;
            grid-row: 2/3;
        }

        .block-module.item4 {
            grid-column: 2/3;
            grid-row: 2/3;
        }

        .block-module .post-filter-inner {
            position: relative;
            float: left;
            width: 100%;
            height: 140px;
            display: block;
            overflow: hidden;
            border-radius: 5px;
        }

        .modal-grid {
            position: relative;
            margin: 0 0 10px;
        }

        div#mega-wrap1 {
            position: relative;
            background: var(--footer-bg-color);
            overflow: hidden;
        }

        span.post-tag-fly {
            position: absolute;
