        }

        .blog-posts .widget-title h3,
        .raw-box .widget-title h3,
        .sidebar .widget-title h3,
        .title-wrap h3,
        .related-runs .widget-title h3 {
            position: relative;
            float: left;
            font-family: var(--title-font);
            height: 32px;
            font-size: 17px;
            color: var(--theme-text-color);
            text-transform: uppercase;
            font-weight: 700;
            line-height: 32px;
            padding: 0 12px 0 0;
            margin: 0;
        }

        .blog-posts .widget-title h3:before,
        .raw-box .widget-title h3:before,
        .sidebar .widget-title h3:before,
        .title-wrap h3:before,
        .related-runs .widget-title h3:before {
            content: "";
            height: 4px;
            width: 60px;
            background-color: var(--button-bg-color);
            position: absolute;
            bottom: 0;
            left: 0;
            border-radius: 10px;
        }

        .blog-posts .widget-title h3:after,
        .raw-box .widget-title h3:after,
        .sidebar .widget-title h3:after,
        .title-wrap h3:after,
        .related-runs .widget-title h3:after {
            content: "";
            height: 5px;
            width: 5px;
            background-color: var(--button-bg-color);
            position: absolute;
            bottom: -1px;
            left: 65px;
            border-radius: 50px;
        }

        .rtl .blog-posts .widget-title h3,
        .rtl .raw-box .widget-title h3,
        .rtl .sidebar .widget-title h3,
        .rtl .related-runs .widget-title h3 {
            float: right;
            padding: 0 0 0 12px;
        }

        .rtl .blog-posts .widget-title h3:before,
        .rtl .raw-box .widget-title h3:before,
        .rtl .sidebar .widget-title h3:before,
        .rtl .title-wrap h3:before,
        .rtl .related-runs .widget-title h3:before {
            left: initial;
            right: 0;
        }

        .rtl .blog-posts .widget-title h3:after,
        .rtl .raw-box .widget-title h3:after,
        .rtl .sidebar .widget-title h3:after,
        .rtl .title-wrap h3:after,
        .rtl .related-runs .widget-title h3:after {
