        }

        #blog-pager {
            position: relative;
            display: flex;
            margin: 10px auto 30px;
            justify-content: center;
            align-items: center;
            align-content: center;
        }

        .blog-pager a,
        .blog-pager span {
            min-width: 32px;
            height: 32px;
            box-sizing: border-box;
            padding: 0 10px;
            margin: 0 5px 0 0;
            transition: all .17s ease;
        }

        .blog-pager span.page-dots {
            min-width: 20px;
            font-size: 16px;
            color: var(--pager-text-color);
            font-weight: 400;
            line-height: 32px;
            padding: 0
        }

        .blog-pager .page-of {
            display: none;
            width: auto;
            float: right;
            border-color: rgba(0, 0, 0, 0);
            margin: 0
        }

        .blog-pager .page-active,
        .blog-pager a:hover {
            background-color: rgb(157 157 157 / 0.20);
            color: var(--theme-text-color);
            border-color: rgb(157 157 157 / 0.50)
        }

        .blog-pager .page-prev:before,
        .blog-pager .page-next:before {
            font-family: 'Material Icons Round';
            font-size: 11px;
            font-weight: 400
        }

        .blog-pager .page-prev:before {
            content: '\e5cb'
        }

        .blog-pager .page-next:before {
            content: '\e5cc'
        }

        .blog-pager .blog-pager-newer-link,
        .blog-pager .blog-pager-older-link {
            float: left;
            display: inline-block;
            width: auto;
            padding: 0 10px;
            margin: 0
        }

        .blog-pager .blog-pager-older-link {
            float: right
        }

        #blog-pager .load-more {
            display: inline-block;
            height: 34px;
            background-color: var(--button-bg-color);
            font-size: 14px;
            color: var(--button-text-color);
            font-weight: 400;
            line-height: 34px;
            box-sizing: border-box;
            padding: 0 30px;
            margin: 0;
            border: 1px solid rgba(0, 0, 0, .1);
            border-bottom-width: 2px;
            border-radius: 2px
        }

        #blog-pager .load-more:after {
            content: '\e5cf';
            font-family: 'Material Icons Round';
            font-size: 22px;
            font-weight: 400;
            margin: 0;
            vertical-align: middle;
        }

        #blog-pager .load-more:hover {
            opacity: 0.8
        }

        #blog-pager .load-more.no-more {
            background-color: rgba(155, 155, 155, 0.05);
            color: var(--button-bg-color)
        }

        #blog-pager .loading,
        #blog-pager .no-more {
            display: none
        }

        #blog-pager .loading .loader {
            position: relative;
            height: 100%;
            overflow: hidden;
            display: block;
            margin: 0
        }

        #blog-pager .loading .loader {
            height: 34px
        }

        #blog-pager .no-more.show {
            display: inline-block
        }

        #blog-pager .loading .loader:after {
            width: 26px;
            height: 26px;
            margin: -15px 0 0 -15px
        }

        #blog-pager .loading .loader:after {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            width: 28px;
            height: 28px;
            margin: -16px 0 0 -16px;
            border: 2px solid var(--button-bg-color);
            border-right-color: rgba(155, 155, 155, 0.2);
            border-radius: 100%;
            animation: spinner 1.1s infinite linear;
            transform-origin: center
        }

        @-webkit-keyframes spinner {
            0% {
                -webkit-transform: rotate(0deg);
                transform: rotate(0deg)
            }

            to {
                -webkit-transform: rotate(1turn);
                transform: rotate(1turn)
            }
        }

        @keyframes spinner {
            0% {
                -webkit-transform: rotate(0deg);
                transform: rotate(0deg)
            }

            to {
                -webkit-transform: rotate(1turn);
                transform: rotate(1turn)
            }
        }

        .archive #blog-pager,
        .home .blog-pager .blog-pager-newer-link,
        .home .blog-pager .blog-pager-older-link {
            display: none
        }

        .loading-frame {
            -webkit-animation-duration: .5s;
            animation-duration: .5s;
            -webkit-animation-fill-mode: both;
            animation-fill-mode: both
        }

        @keyframes fadeIn {
            from {
                opacity: 0
            }

            to {
                opacity: 1
            }
        }

        .run-time {
            animation-name: fadeIn
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translate3d(0, 5px, 0)
            }

            to {
                opacity: 1;
                transform: translate3d(0, 0, 0)
            }
        }

        .load-time {
            animation-name: fadeInUp
        }

        .loading-frame {
            -webkit-animation-duration: .5s;
            animation-duration: .5s;
            -webkit-animation-fill-mode: both;
            animation-fill-mode: both
        }

        @keyframes fadeIn {
            from {
                opacity: 0
            }

            to {
                opacity: 1
            }
        }

        .run-time {
            animation-name: fadeIn
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translate3d(0, 5px, 0)
            }

            to {
                opacity: 1;
                transform: translate3d(0, 0, 0)
            }
        }

        .load-time {
            animation-name: fadeInUp
        }

        @-webkit-keyframes slidein {
            0% {
                opacity: 0
            }

            20% {
                opacity: 1;
                bottom: 0
            }

            50% {
                opacity: 1;
                bottom: 0
            }

            80% {
                opacity: 1;
                bottom: 0
            }

            100% {
                opacity: 0;
                bottom: -70px;
                visibility: hidden
            }
        }

        @keyframes slidein {
            0% {
                opacity: 0
            }

            20% {
                opacity: 1;
                bottom: 0
            }

            50% {
                opacity: 1;
                bottom: 0
            }

            80% {
                opacity: 1;
                bottom: 0
            }

            100% {
                opacity: 0;
                bottom: -70px;
                visibility: hidden
            }
        }

        .archive #blog-pager,
        .home .blog-pager .blog-pager-newer-link,
        .home .blog-pager .blog-pager-older-link {
            display: none
        }

