        .sibForm .widget-content {
            position: relative;
            border: 1px solid rgb(112 112 112 / 0.15);
            z-index: 11;
            text-align: center;
            font-weight: 600;
            box-sizing: border-box;
            padding: 20px 20px 5px;
            border-radius: 4px;
        }

        .sibForm:after {
            content: '';
            display: block;
            position: absolute;
            bottom: 0;
            right: 0;
            width: 100px;
            height: 100px;
            opacity: 0.20;
            background: var(--button-bg-color);
            border-radius: 100px 0 0;
        }

        .sibForm .follow-by-email-caption {
            font-size: 13px;
