            margin: 0 0 15px;
            display: block;
            padding: 0 10px;
            overflow: hidden
        }

        .sibForm .follow-by-email:before {
            content: '\e7f4';
            position: absolute;
            font-family: 'Material Icons Round';
            color: var(--email-text-color);
            top: 0;
            left: 50%;
            width: 34px;
            overflow: hidden;
            height: 34px;
            background-color: var(--email-bg-color);
            font-size: 20px;
            font-weight: 400;
            line-height: 34px;
            text-align: center;
            transform: translate(-50%, -30%);
            margin: 0;
            border-radius: 50%;
        }

        .sibForm .follow-by-email-inner {
            position: relative
        }

        .follow-by-email-title {
            font-size: 17px;
            font-weight: 700;
            padding: 7px;
            margin: 15px 0px;
            color: var(--theme-text-color)
        }

        .sibForm .follow-by-email-inner .follow-by-email-address {
            width: 100%;
            height: 32px;
            color: var(--theme-text-color);
            background: var(--input-form);
            font-size: 11px;
            font-family: inherit;
            padding: 0 10px;
            margin: 0 0 10px;
            box-sizing: border-box;
            border: 1px solid rgb(122 122 122 / 0.53);
            border-radius: 4px;
            transition: ease .40s
        }

        .sibForm .follow-by-email-inner .follow-by-email-address:focus {
            border: 1px solid var(--email-bg-color);
        }

        .sibForm .follow-by-email-inner .follow-by-email-address::placeholder {
            color: var(--placeholder-text-color);
